29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
40	import org.springframework.samples.petclinic.rest.validation.CityCapacityExceededException;
41	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitExceededException;
42	import org.springframework.samples.petclinic.rest.validation.DuplicateIdentityException;
43	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
44	import org.springframework.samples.petclinic.rest.validation.InvalidPostcodeException;
45	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
46	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
47	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
48	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.samples.petclinic.service.OwnerAuditor;
51	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Maximum number of owners a single city may hold. A create request whose city already contains
71	     * this many owners is rejected as a conflict.
72	     */
73	    static final int MAX_OWNERS_PER_CITY = 50;
74	
75	    /**
76	     * Maximum number of owners that may be registered on a single day. A create request whose
77	     * registration date already holds this many owners is rejected with 429 Too Many Requests.
78	     */
79	    static final int MAX_OWNERS_PER_DAY = 100;
80	
81	    /**
82	     * Number of owners that may be registered on the current business day before a create/read
83	     * response flags {@code bulkSignupWarning}. Once more than this many owners exist for the day,
84	     * the warning is raised.
85	     */
86	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
87	
88	    private final ClinicService clinicService;
89	
90	    private final OwnerMapper ownerMapper;
91	
92	    private final PetMapper petMapper;
93	
94	    private final VisitMapper visitMapper;
95	
96	    private final OwnerAuditor ownerAuditor;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper,
102	                                 OwnerAuditor ownerAuditor) {
103	        this.clinicService = clinicService;
104	        this.ownerMapper = ownerMapper;
105	        this.petMapper = petMapper;
106	        this.visitMapper = visitMapper;
107	        this.ownerAuditor = ownerAuditor;
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
113	        Collection<Owner> owners;
114	        if (lastName != null) {
115	            owners = this.clinicService.findOwnerByLastName(lastName);
116	        } else {
117	            owners = this.clinicService.findAllOwners();
118	        }
119	        if (owners.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
128	        Owner owner = this.clinicService.findOwnerById(ownerId);
129	        if (owner == null) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        return new ResponseEntity<>(toOwnerDtoWithBulkSignupWarning(owner), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
139	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
140	        if (!missingFields.isEmpty()) {
141	            throw new MissingOwnerFieldsException(missingFields);
142	        }
143	        HttpHeaders headers = new HttpHeaders();
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        if (!PostcodeValidator.isValidForCity(owner.getCity(), owner.getPostcode())) {
146	            throw new InvalidPostcodeException(owner.getPostcode(), owner.getCity());
147	        }
148	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
149	            throw new CityCapacityExceededException(owner.getCity());
150	        }
151	        LocalDate registrationDate = RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate());
152	        if (this.clinicService.countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
153	            throw new DailyOwnerLimitExceededException(registrationDate);
154	        }
155	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
156	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
157	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
158	            Collection<Owner> household =
159	                this.clinicService.findOwnersInHousehold(owner.getLastName(), owner.getAddress());
160	            this.clinicService.joinHousehold(owner, household);
161	        }
162	        // A single identity key (telephone + email + household) drives duplicate detection: reject
163	        // only when the whole key already belongs to another owner.
164	        if (this.clinicService.isDuplicateIdentity(owner)) {
165	            throw new DuplicateIdentityException(owner.getIdentityKey());
166	        }
167	        this.clinicService.saveOwner(owner);
168	        this.ownerAuditor.ownerCreated(owner);
169	        OwnerDto ownerDto = toOwnerDtoWithBulkSignupWarning(owner);
170	        headers.setLocation(UriComponentsBuilder.newInstance()
171	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
172	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
173	    }
174	
175	    /**
176	     * Map an owner to its DTO and stamp {@code bulkSignupWarning}, which reflects whether more than
177	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been registered on the current
178	     * business day.
179	     */
180	    private OwnerDto toOwnerDtoWithBulkSignupWarning(Owner owner) {
181	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
182	        LocalDate today = RegistrationDatePolicy.effectiveDate(null);
183	        ownerDto.setBulkSignupWarning(
184	            this.clinicService.countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
185	        return ownerDto;
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
191	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
192	        if (currentOwner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        currentOwner.setAddress(ownerFieldsDto.getAddress());
196	        currentOwner.setCity(ownerFieldsDto.getCity());
197	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
198	        currentOwner.setLastName(ownerFieldsDto.getLastName());
199	        currentOwner.setTelephone(TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
200	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
201	        this.clinicService.saveOwner(currentOwner);
202	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Transactional
207	    @Override
208	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
209	        Owner owner = this.clinicService.findOwnerById(ownerId);
210	        if (owner == null) {
211	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	        }
213	        this.clinicService.deleteOwner(owner);
214	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
215	    }
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
220	        Owner owner = this.clinicService.findOwnerById(ownerId);
221	        if (owner == null) {
222	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	        }
224	        HttpHeaders headers = new HttpHeaders();
225	        Pet pet = petMapper.toPet(petFieldsDto);
226	        owner.setId(ownerId);
227	        pet.setOwner(owner);
228	        pet.getType().setName(null);
229	        this.clinicService.savePet(pet);
230	        PetDto petDto = petMapper.toPetDto(pet);
231	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
232	            .buildAndExpand(pet.getId()).toUri());
233	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
234	    }
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
239	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
240	        if (currentOwner != null) {
241	            Pet currentPet = this.clinicService.findPetById(petId);
242	            if (currentPet != null) {
243	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
244	                currentPet.setName(petFieldsDto.getName());
245	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
246	                this.clinicService.savePet(currentPet);
247	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
248	            }
249	        }
250	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	    }
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Override
255	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
256	        HttpHeaders headers = new HttpHeaders();
257	        Visit visit = visitMapper.toVisit(visitFieldsDto);
258	        Pet pet = new Pet();
259	        pet.setId(petId);
260	        visit.setPet(pet);
261	        this.clinicService.saveVisit(visit);
262	        VisitDto visitDto = visitMapper.toVisitDto(visit);
263	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
264	            .buildAndExpand(visit.getId()).toUri());
265	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
266	    }
267	
268	
269	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
270	    @Override
271	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
272	        Owner owner = this.clinicService.findOwnerById(ownerId);
273	        if (owner != null) {
274	            Pet pet = owner.getPet(petId);
275	            if (pet != null) {
276	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
277	            }
278	        }
279	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
280	    }
281	}
