33	/**
34	 * Mostly used as a facade so all controllers have a single point of entry
35	 *
36	 * @author Michael Isvy
37	 * @author Vitaliy Fedoriv
38	 */
39	public interface ClinicService {
40	
41		Pet findPetById(int id) throws DataAccessException;
42		Collection<Pet> findAllPets() throws DataAccessException;
43	    Page<Pet> findPets(Pageable pageable) throws DataAccessException;
44		void savePet(Pet pet) throws DataAccessException;
45		void deletePet(Pet pet) throws DataAccessException;
46	
47		Collection<Visit> findVisitsByPetId(int petId);
48		Visit findVisitById(int visitId) throws DataAccessException;
49		Collection<Visit> findAllVisits() throws DataAccessException;
50		void saveVisit(Visit visit) throws DataAccessException;
51		void deleteVisit(Visit visit) throws DataAccessException;
52		Vet findVetById(int id) throws DataAccessException;
53		Collection<Vet> findVets() throws DataAccessException;
54		Collection<Vet> findAllVets() throws DataAccessException;
55		void saveVet(Vet vet) throws DataAccessException;
56		void deleteVet(Vet vet) throws DataAccessException;
57		Owner findOwnerById(int id) throws DataAccessException;
58		Collection<Owner> findAllOwners() throws DataAccessException;
59		Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException;
60		void saveOwner(Owner owner) throws DataAccessException;
61		void deleteOwner(Owner owner) throws DataAccessException;
62		Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException;
63		Collection<Owner> findOwnerByTelephone(String telephone) throws DataAccessException;
64	
65		/**
66		 * Determine whether a persisted owner already shares the given owner's identity key
67		 * (see {@link Owner#getIdentityKey()}) — the single signal used to reject duplicate owners.
68		 * Only an exact match of the whole key counts as a duplicate.
69		 *
70		 * @param owner the candidate owner whose identity key is checked
71		 * @return {@code true} if an existing owner has the same identity key, {@code false} otherwise
72		 */
73		boolean isDuplicateIdentity(Owner owner) throws DataAccessException;
74	
75		/**
76		 * Retrieve the owners whose email matches the given value, compared case-insensitively.
77		 *
78		 * @param email the email to match, case-insensitively
79		 * @return a <code>Collection</code> of matching <code>Owner</code>s (empty if none)
80		 */
81		Collection<Owner> findOwnerByEmail(String email) throws DataAccessException;
82	
83		/**
84		 * Count the number of owners located in the given city.
85		 *
86		 * @param city the city to match
87		 * @return the number of persisted owners in that city
88		 */
89		long countOwnersByCity(String city) throws DataAccessException;
90	
91		/**
92		 * Count the number of owners registered on the given date.
93		 *
94		 * @param registrationDate the registration date to match
95		 * @return the number of persisted owners whose registration date equals the given date
96		 */
97		long countOwnersRegisteredOn(LocalDate registrationDate) throws DataAccessException;
98	
99		/**
100		 * Retrieve the owners that belong to the same household as the given last name and address, i.e.
101		 * whose last name and address both match when compared case-insensitively with collapsed
102		 * whitespace.
103		 *
104		 * @param lastName the last name to match
105		 * @param address the address to match
106		 * @return a <code>Collection</code> of matching <code>Owner</code>s (empty if none)
107		 */
108		Collection<Owner> findOwnersInHousehold(String lastName, String address) throws DataAccessException;
109	
110		/**
111		 * Assign the given owner and every existing member of its household the same stable
112		 * {@code householdId}, persisting the change for any member that does not yet carry it. Used when
113		 * an owner is knowingly created into a shared household.
114		 *
115		 * @param owner the new owner joining the household
116		 * @param existingMembers the owners already in the household (may be empty)
117		 * @return the shared household identifier assigned to the owner
118		 */
119		String joinHousehold(Owner owner, Collection<Owner> existingMembers) throws DataAccessException;
120	
121		PetType findPetTypeById(int petTypeId);
122		Collection<PetType> findAllPetTypes() throws DataAccessException;
123		Collection<PetType> findPetTypes() throws DataAccessException;
124		void savePetType(PetType petType) throws DataAccessException;
125		void deletePetType(PetType petType) throws DataAccessException;
126		Specialty findSpecialtyById(int specialtyId);
127		Collection<Specialty> findAllSpecialties() throws DataAccessException;
128		void saveSpecialty(Specialty specialty) throws DataAccessException;
129		void deleteSpecialty(Specialty specialty) throws DataAccessException;
130	
131	    List<Specialty> findSpecialtiesByNameIn(Set<String> names) throws DataAccessException;
132	}
