16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
20	
21	import jakarta.persistence.*;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "postcode")
48	    private String postcode;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    private String email;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "household_size")
71	    private Integer householdSize;
72	
73	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
74	    private Set<Pet> pets;
75	
76	    /**
77	     * Resolve the registration date at creation time: default it to the server's
78	     * current date when none was supplied, and roll a weekend date forward to the
79	     * next business day so every value derived from it (such as the membership
80	     * number's year segment) uses the adjusted date.
81	     */
82	    @PrePersist
83	    private void resolveRegistrationDate() {
84	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
85	    }
86	
87	    public String getAddress() {
88	        return this.address;
89	    }
90	
91	    public void setAddress(String address) {
92	        this.address = address;
93	    }
94	
95	    public String getCity() {
96	        return this.city;
97	    }
98	
99	    public void setCity(String city) {
100	        this.city = city;
101	    }
102	
103	    public String getPostcode() {
104	        return this.postcode;
105	    }
106	
107	    public void setPostcode(String postcode) {
108	        this.postcode = postcode;
109	    }
110	
111	    /**
112	     * The owner's locality: the canonical region derived by {@link Locality} from
113	     * its {@link #postcode} (preferred) and {@link #city}, or {@code "UNKNOWN"}
114	     * when neither resolves to a known region.
115	     */
116	    public String getLocality() {
117	        return Locality.of(this.city, this.postcode);
