34	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
35	
36	    /** Common street-type abbreviations expanded to their canonical full words. */
37	    private static final Map<String, String> ABBREVIATIONS = Map.of(
38	        "ST", "STREET",
39	        "RD", "ROAD",
40	        "AVE", "AVENUE");
41	
42	    private AddressNormalizer() {
43	    }
