18	import java.time.DayOfWeek;
19	import java.time.LocalDate;
20	import java.time.temporal.TemporalAdjusters;
21	
22	/**
23	 * Resolves the effective registration date for an owner.
24	 *
25	 * <p>An owner is always registered on a business day. The supplied date defaults
26	 * to the server's current date when none was provided, and a date that falls on a
27	 * weekend (Saturday or Sunday) is rolled forward to the following Monday. The
28	 * resulting date is the single source of truth for everything derived from the
29	 * registration date (the stored value, the membership number's year segment, and
30	 * the per-day create-limit).
31	 */
32	public final class RegistrationDatePolicy {
33	
34	    private RegistrationDatePolicy() {
35	    }
36	
37	    /**
38	     * Resolve the effective, business-day registration date.
39	     *
40	     * @param suppliedDate the date supplied in the request, or {@code null} to use
41	     *                     the server's current date
42	     * @return the supplied-or-defaulted date, rolled forward to the next Monday
43	     *         when it falls on a weekend
44	     */
45	    public static LocalDate effectiveDate(LocalDate suppliedDate) {
46	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
47	        DayOfWeek dayOfWeek = date.getDayOfWeek();
48	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
49	            return date.with(TemporalAdjusters.next(DayOfWeek.MONDAY));
50	        }
51	        return date;
52	    }
53	}
