16	package org.springframework.samples.petclinic.service;
17	
18	import org.springframework.samples.petclinic.model.Owner;
19	import org.springframework.samples.petclinic.repository.OwnerRepository;
20	import org.springframework.samples.petclinic.util.TextNormalizer;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Counts the owners already registered that share a given owner's name.
25	 *
26	 * <p>Two owners are namesakes when both their first and last names match,
27	 * compared case-insensitively (surrounding and repeated whitespace is also
28	 * ignored, consistent with the rest of the application's name handling).
29	 */
30	@Component
31	public class NamesakeCounter {
32	
33	    private final OwnerRepository ownerRepository;
34	
35	    public NamesakeCounter(OwnerRepository ownerRepository) {
36	        this.ownerRepository = ownerRepository;
37	    }
38	
39	    /**
40	     * Count the currently persisted owners that share the given owner's first
41	     * and last name.
42	     *
43	     * @param owner the owner being registered
44	     * @return the number of existing namesakes
45	     */
46	    public int count(Owner owner) {
47	        String firstName = TextNormalizer.normalizeForComparison(owner.getFirstName());
48	        String lastName = TextNormalizer.normalizeForComparison(owner.getLastName());
49	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
50	            .filter(other -> TextNormalizer.normalizeForComparison(other.getLastName()).equals(lastName))
51	            .filter(other -> TextNormalizer.normalizeForComparison(other.getFirstName()).equals(firstName))
52	            .count();
53	    }
54	}
