16	package org.springframework.samples.petclinic.service;
17	
18	import org.springframework.samples.petclinic.model.Owner;
19	import org.springframework.samples.petclinic.repository.OwnerRepository;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Counts the members of an owner's household — the owners that share its
24	 * {@link Owner#getHouseholdId() household id}.
25	 *
26	 * <p>Household members always share a last name (the household id is derived
27	 * from the last name and address), so members are found via the same
28	 * case-insensitive last-name lookup used elsewhere and then narrowed to the
29	 * matching household id.
30	 */
31	@Component
32	public class HouseholdMemberCounter {
33	
34	    private final OwnerRepository ownerRepository;
35	
36	    public HouseholdMemberCounter(OwnerRepository ownerRepository) {
37	        this.ownerRepository = ownerRepository;
38	    }
39	
40	    /**
41	     * Count the members of the given owner's household, including the owner
42	     * itself. An owner with no household id is a household of one.
43	     *
44	     * @param owner the owner being registered
45	     * @return the number of household members once the owner is included
46	     */
47	    public int count(Owner owner) {
48	        String householdId = owner.getHouseholdId();
49	        if (householdId == null) {
50	            return 1;
51	        }
52	        long others = ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
53	            .filter(other -> householdId.equals(other.getHouseholdId()))
54	            .count();
55	        return (int) others + 1;
56	    }
57	}
